from typing import List

def resultsArray(nums: List[int], k: int) -> List[int]:
    n = len(nums)
    results = []

    for i in range(n - k + 1):
        subarray = nums[i : i + k]

        # Check if consecutive and sorted in ascending order
        is_consecutive_sorted = True
        max_val = subarray[0]

        for j in range(k):
            if subarray[j] != subarray[0] + j:
                is_consecutive_sorted = False
                break
            if subarray[j] > max_val:
                max_val = subarray[j]

        if is_consecutive_sorted:
            results.append(max_val)
        else:
            results.append(-1)

    return results

def validSequence(word1: str, word2: str):
    n = len(word1)
    m = len(word2)

    L = [0] * m
    curr = 0
    for i in range(m):
        while curr < n and word1[curr] != word2[i]:
            curr += 1
        if curr >= n:
            return []
        L[i] = curr
        curr += 1

    R = [0] * m
    curr = n - 1
    for i in range(m - 1, -1, -1):
        while curr >= 0 and word1[curr] != word2[i]:
            curr -= 1
        if curr < 0:
            return []
        R[i] = curr
        curr -= 1

    P = [0] * m
    prev_p = -1
    for i in range(m):
        P[i] = max(L[i], prev_p + 1)
        prev_p = P[i]

    IsP_correct = [True] * m
    for i in range(m):
        if P[i] > R[i]:
            IsP_correct[i] = False
        if i > 0 and not IsP_correct[i-1]:
            IsP_correct[i] = False

    A = [L[j] - j for j in range(m)]
    B = [R[j] - j for j in range(m)]

    minB_suffix = [0] * (m + 1)
    minB_suffix[m] = float('inf')
    for i in range(m - 1, -1, -1):
        minB_suffix[i] = min(B[i], minB_suffix[i+1])

    J_max = -1
    for j in range(m):
        if A[j] > minB_suffix[j]:
            J_max = max(J_max, j)

    candidates = []

    # Case: No mismatch (all word1[i_k] == word2[k])
    possible_none = True
    for i in range(m):
        if not IsP_correct[i]:
            possible_none = False
            break
    if possible_none:
        candidates.append(list(P))

    # Case: Mismatch at position k (word1[i_k] can be anything)
    for k in range(m):
        if k > 0 and not IsP_correct[k-1]:
            continue

        p_min = P[k-1] + 1 if k > 0 else 0

        if k == m - 1:
            p_max = n - 1
        else:
            p_max = minB_suffix[k+1] + (k - 1)

        if p_min <= p_max and k >= J_max:
            res = [0] * m
            for j in range(k):
                res[j] = P[j]
            res[k] = p_min
            prev = res[k]
            for j in range(k + 1, m):
                res[j] = max(L[j], prev + 1)
                prev = res[j]
            candidates.append(res)

    if not candidates:
        return []

    return min(candidates)

from typing import List

def minArraySum(nums: List[int], k: int, op1: int, op2: int) -> int:
    # dp[j][l] is the minimum sum of elements processed so far using j op1 and l op2.
    n = len(nums)
    dp = [[float('inf')] * (op2 + 1) for _ in range(op1 + 1)]
    dp[0][0] = 0

    for x in nums:
        new_dp = [[float('inf')] * (op2 + 1) for _ in range(op1 + 1)]
        r0 = x
        r1 = (x + 1) // 2
        r2 = x - k if x >= k else x
        # For both, we want the minimum possible value.
        v_a = r1 - k if r1 >= k else r1
        v_b = (x - k + 1) // 2 if x >= k else x
        r3 = min(v_a, v_b)

        for j in range(op1 + 1):
            for l in range(op2 + 1):
                if dp[j][l] == float('inf'):
                    continue

                # Option 0: No op
                new_dp[j][l] = min(new_dp[j][l], dp[j][l] + r0)

                # Option 1: Op1
                if j + 1 <= op1:
                    new_dp[j+1][l] = min(new_dp[j+1][l], dp[j][l] + r1)

                # Option 2: Op2
                if l + 1 <= op2:
                    new_dp[j][l+1] = min(new_dp[j][l+1], dp[j][l] + r2)

                # Option 3: Both
                if j + 1 <= op1 and l + 1 <= op2:
                    new_dp[j+1][l+1] = min(new_dp[j+1][l+1], dp[j][l] + r3)
        dp = new_dp

    ans = float('inf')
    for j in range(op1 + 1):
        for l in range(op2 + 1):
            ans = min(ans, dp[j][l])
    return int(ans)
